import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ProdutoService } from '../../services/produto.service';
import { TipoProduto, TipoProdutoService } from '../../services/tipo-produto.service';

@Component({
  selector: 'app-form-produto',
  templateUrl: './form-produto.component.html',
  styleUrls: ['./form-produto.component.css']
})
export class FormProdutoComponent implements OnInit {
  form!: FormGroup;
  tipos: TipoProduto[] = [];
  mensagemSucesso: string = '';
  mensagemErro: string = '';
  salvando: boolean = false;

  constructor(
    private fb: FormBuilder,
    private produtoService: ProdutoService,
    private tipoProdutoService: TipoProdutoService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.form = this.fb.group({
      nome: ['', [Validators.required, Validators.minLength(2)]],
      preco: [null, [Validators.required, Validators.min(0.01)]],
      tipoProdutoId: [null, Validators.required]
    });

    this.tipoProdutoService.listar().subscribe({
      next: (dados) => this.tipos = dados,
      error: () => this.mensagemErro = 'Erro ao carregar tipos de produto.'
    });
  }

  get f() { return this.form.controls; }

  salvar(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.salvando = true;
    this.mensagemErro = '';
    this.mensagemSucesso = '';

    this.produtoService.salvar(this.form.value).subscribe({
      next: (produto) => {
        this.mensagemSucesso = `Produto "${produto.nome}" cadastrado com sucesso!`;
        this.form.reset();
        this.salvando = false;
        setTimeout(() => this.router.navigate(['/produtos']), 1500);
      },
      error: (err) => {
        if (err.error && typeof err.error === 'object') {
          const erros = Object.values(err.error).join(' | ');
          this.mensagemErro = erros;
        } else {
          this.mensagemErro = 'Erro ao salvar produto.';
        }
        this.salvando = false;
      }
    });
  }
}
<div class="page-header">
  <h2>Cadastrar Produto</h2>
</div>

<div class="alert alert-sucesso" *ngIf="mensagemSucesso">{{ mensagemSucesso }}</div>
<div class="alert alert-erro" *ngIf="mensagemErro">{{ mensagemErro }}</div>

<div class="card">
  <form [formGroup]="form" (ngSubmit)="salvar()">

    <div class="campo">
      <label for="nome">Nome do Produto</label>
      <input id="nome" type="text" formControlName="nome" placeholder="Ex: Notebook Dell" />
      <span class="erro" *ngIf="f['nome'].touched && f['nome'].errors?.['required']">
        O nome é obrigatório.
      </span>
      <span class="erro" *ngIf="f['nome'].touched && f['nome'].errors?.['minlength']">
        O nome deve ter pelo menos 2 caracteres.
      </span>
    </div>

    <div class="campo">
      <label for="preco">Preço (R$)</label>
      <input id="preco" type="number" step="0.01" formControlName="preco" placeholder="Ex: 99.90" />
      <span class="erro" *ngIf="f['preco'].touched && f['preco'].errors?.['required']">
        O preço é obrigatório.
      </span>
      <span class="erro" *ngIf="f['preco'].touched && f['preco'].errors?.['min']">
        O preço deve ser maior que zero.
      </span>
    </div>

    <div class="campo">
      <label for="tipo">Tipo de Produto</label>
      <select id="tipo" formControlName="tipoProdutoId">
        <option [ngValue]="null" disabled>Selecione um tipo...</option>
        <option *ngFor="let tipo of tipos" [value]="tipo.id">{{ tipo.nome }}</option>
      </select>
      <span class="erro" *ngIf="f['tipoProdutoId'].touched && f['tipoProdutoId'].errors?.['required']">
        O tipo de produto é obrigatório.
      </span>
    </div>

    <div class="acoes">
      <button type="submit" class="btn btn-salvar" [disabled]="salvando">
        {{ salvando ? 'Salvando...' : 'Cadastrar Produto' }}
      </button>
      <a routerLink="/produtos" class="btn btn-cancelar">Cancelar</a>
    </div>

  </form>
</div>
